toolu_01J9s7oSWWkStsUJzxgiDT5G.command:
mkdir -p /tmp/sloparena-readme-preview/img && cd /tmp/sloparena-readme-preview && WT=/home/binoui/Projects/SlopArena/.worktrees/friends-onboarding && \
magick "$WT/docs/design/references/sloparena-visual-identity/visual-reference-study.png" -resize 1100x -quality 80 img/hero.jpg && \
for s in table_manners splash_deck log_off; do magick "$WT/client/Unity/Assets/Resources/UI/Stages/$s.png" -resize 520x -quality 80 "img/$s.jpg"; done && ls -la img/ && cat > /tmp/sloparena-readme-preview/build.py <<'EOF'
import base64, re, sys
from pathlib import Path
import markdown

wt = Path(sys.argv[1]); out = Path(sys.argv[2]); img = Path(sys.argv[3])
text = (wt / "README.md").read_text(encoding="utf-8")
def data_uri(name):
    return "data:image/jpeg;base64," + base64.b64encode((img / name).read_bytes()).decode()
text = text.replace("docs/design/references/sloparena-visual-identity/visual-reference-study.png", data_uri("hero.jpg"))
for s in ("table_manners", "splash_deck", "log_off"):
    text = text.replace(f"client/Unity/Assets/Resources/UI/Stages/{s}.png", data_uri(f"{s}.jpg"))
# Let python-markdown render markdown inside <details> and centered <p> blocks like GitHub does.
text = text.replace("<details>", '<details markdown="1">')
body = markdown.markdown(text, extensions=["tables", "fenced_code", "md_in_html", "toc"])
# Make relative repo links point at GitHub so they work from the preview.
body = re.sub(r'href="(?!https?:|#|mailto:)([^"]+)"', r'href="https://github.com/Binoui/SLOPArena/blob/main/\1"', body)
css = """
:root{color-scheme:light dark}
