"""Read-only: which tracked C# / asmdef files depend on code that only exists locally."""
import json, os, re, subprocess, sys
from pathlib import Path
WT, MAIN = Path(sys.argv[1]), Path(sys.argv[2])
U = Path("client/Unity")
tracked = {Path(p) for p in subprocess.run(["git","-C",str(WT),"ls-files","-z","--",str(U)],
           stdout=subprocess.PIPE, check=True).stdout.decode().split("\0") if p}
NS = re.compile(r"^\s*namespace\s+([A-Za-z_][\w.]*)", re.M)
local_ns, local_asm, local_asm_guid = {}, {}, {}
for base in ("Assets", "Packages"):
    for root, _, files in os.walk(MAIN / U / base):
        for f in files:
            full = Path(root) / f; rel = full.relative_to(MAIN)
            if rel in tracked: continue
            if f.endswith(".cs"):
                for ns in NS.findall(full.read_text(errors="replace")):
                    top = ".".join(ns.split(".")[:2])
                    local_ns.setdefault(top, str(rel.parent))
            elif f.endswith(".asmdef"):
                try: name = json.loads(full.read_text(errors="replace")).get("name")
                except Exception: continue
                local_asm[name] = str(rel)
                m = re.search(r"^guid:\s*([0-9a-f]{32})", (full.parent / (f + ".meta")).read_text(errors="replace"), re.M) if (full.parent / (f + ".meta")).exists() else None
                if m: local_asm_guid[m.group(1)] = name
# ignore namespaces that tracked code itself declares (project namespaces)
tracked_ns = set()
for rel in tracked:
    if rel.suffix == ".cs":
        for ns in NS.findall((WT / rel).read_text(errors="replace")):
            tracked_ns.add(".".join(ns.split(".")[:2]))
vendor_ns = {ns: src for ns, src in local_ns.items() if ns not in tracked_ns and not ns.startswith(("Unity", "System"))}
print(f"local-only namespaces (top 2 segments): {len(vendor_ns)}")
hits = {}
for rel in sorted(tracked):
    if rel.suffix != ".cs": continue
    text = (WT / rel).read_text(errors="replace")
    for ns in vendor_ns:
        if re.search(rf"^\s*using\s+(static\s+)?{re.escape(ns)}\s*;|\b{re.escape(ns)}\.\w", text, re.M):
            hits.setdefault(ns, []).append(str(rel).replace("client/Unity/", ""))
for ns, files in sorted(hits.items(), key=lambda kv: -len(kv[1])):
    print(f"\n{ns}  (declared under {vendor_ns[ns]})  <- {len(files)} tracked .cs files")
    for f in files[:12]: print("   ", f)
    if len(files) > 12: print(f"    ... +{len(files)-12} more")
print("\n--- tracked asmdefs referencing local-only assemblies ---")
for rel in sorted(tracked):
    if rel.suffix != ".asmdef": continue
    d = json.loads((WT / rel).read_text(errors="replace"))
    bad = [r for r in d.get("references", []) if r in local_asm or (r.startswith("GUID:") and r[5:] in local_asm_guid)]
    if bad:
        print(f"  {rel}: {[local_asm_guid.get(r[5:], r) if r.startswith('GUID:') else r for r in bad]}  defineConstraints={d.get('defineConstraints', [])}  versionDefines={[v.get('define') for v in d.get('versionDefines', [])]}")
EOF
