for rel in tracked:
    if rel.suffix == ".cs":
        for ns in NS.findall((WT / rel).read_text(errors="replace")):
            tracked_ns.add(".".join(ns.split(".")[:2]))
vendor_ns = {ns: src for ns, src in local_ns.items() if ns not in tracked_ns and not ns.startswith(("Unity", "System"))}
print(f"local-only namespaces (top 2 segments): {len(vendor_ns)}")
hits = {}
for rel in sorted(tracked):
    if rel.suffix != ".cs": continue
