input.command:
python3 -I - <<'EOF'
import json, struct
from pathlib import Path
for pkg in ("fightguy", "manki", "wibou", "bonk"):
    b = Path(f"content-cooked/{pkg}/poses.bin").read_bytes()
    magic, ver, bones, anims = struct.unpack_from("<IIII", b, 0); pos = 16; names = []
    for _ in range(bones):
        (n,) = struct.unpack_from("<I", b, pos); pos += 4; names.append(b[pos:pos+n].decode()); pos += n
    rt = json.loads(Path(f"content-cooked/{pkg}/character.runtime.json").read_text())
    defs = rt.get("character", rt).get("hurtboxBoneDefs") if isinstance(rt.get("character"), dict) else None
    if defs is None:
        def find(o):
            if isinstance(o, dict):
                if "hurtboxBoneDefs" in o: return o["hurtboxBoneDefs"]
                for v in o.values():
                    r = find(v)
                    if r is not None: return r
            elif isinstance(o, list):
                for v in o:
                    r = find(v)
                    if r is not None: return r
        defs = find(rt)
    print(f"== {pkg}: sim pairs def[i] with poses.bin bone[i]")
    for i, d in enumerate(defs):
        bone = names[i] if i < len(names) else "-"
        intended = d["boneId"].replace("bone.", "")
        flag = "" if intended.replace("-", "").lower() in bone.replace(":", "").lower().replace("mixamorig", "") else "   <-- MISMATCH"
        print(f"   [{i}] radius {d['radius']:.2f} meant for {intended:<11} -> placed on {bone}{flag}")
EOF

