149	public static class CharacterPackageAssembler
150	{
151	    public const int ManifestSchemaVersion = 1;
152	    public const string RuntimePath = "character.runtime.json";
153	    public const string PosePath = "poses.bin";
154	    public const string BindingPath = "client.bindings";
155	    public const string ManifestPath = "manifest.json";
156	    private static readonly string[] PayloadPaths = { RuntimePath, PosePath, BindingPath };
157	
158	    public static CharacterPackageAssemblyResult Assemble(CharacterPackageAssemblyInput input)
159	    {
160	        var diagnostics = new List<CharacterDiagnostic>();
161	        ValidateInput(input, diagnostics);
162	        if (diagnostics.Any(x => x.Severity == CharacterDiagnosticSeverity.Error)) return CharacterPackageAssemblyResult.Failure(diagnostics);
163	
164	        var payloads = new[]
165	        {
166	            (Path: RuntimePath, Bytes: input.RuntimeBytes),
167	            (Path: PosePath, Bytes: input.PoseBytes),
168	            (Path: BindingPath, Bytes: input.BindingBytes),
169	        };
170	        ValidateCrossPayloads(input, payloads, diagnostics);
171	        if (diagnostics.Any(x => x.Severity == CharacterDiagnosticSeverity.Error)) return CharacterPackageAssemblyResult.Failure(diagnostics);
172	
173	        string cookedHash = HashFramed(payloads);
174	        var payloadInfo = payloads.Select(x => new CharacterPackagePayloadInfo(x.Path, Hash(x.Bytes), x.Bytes.LongLength)).ToArray();
175	        byte[] placeholder = WriteManifest(input, payloadInfo, cookedHash, "");
176	        string packageHash = Hash(Concat(FramedBytes(payloads), placeholder));
177	        byte[] manifest = WriteManifest(input, payloadInfo, cookedHash, packageHash);
178	        return new CharacterPackageAssemblyResult(manifest, input.RuntimeBytes, input.PoseBytes, input.BindingBytes,
179	            input.SourceHash, cookedHash, packageHash, payloadInfo, diagnostics);
180	    }
181	
182	    public static CharacterPackageVerificationResult Verify(IReadOnlyDictionary<string, byte[]> files)
183	    {
184	        var diagnostics = new List<CharacterDiagnostic>();
185	        if (files == null)
186	        {
187	            diagnostics.Add(Error("package.files.missing", "package", "Package files are missing."));
188	            return new CharacterPackageVerificationResult(diagnostics);
189	        }
190	        var expected = new HashSet<string>(PayloadPaths.Concat(new[] { ManifestPath }), StringComparer.Ordinal);
191	        foreach (string path in files.Keys)
192	        {
193	            if (!expected.Contains(path)) diagnostics.Add(Error("package.files.extra", path, "Unexpected package file."));
194	            else if (files[path] == null) diagnostics.Add(Error("package.files.null", path, "Package file bytes are null."));
195	        }
196	        foreach (string path in expected)
197	            if (!files.ContainsKey(path)) diagnostics.Add(Error("package.files.missing", path, "Required package file is missing."));
198	        if (diagnostics.Any(x => x.Severity == CharacterDiagnosticSeverity.Error)) return new CharacterPackageVerificationResult(diagnostics);
199	
200	        ManifestData? manifest = ParseManifest(files[ManifestPath], diagnostics);
201	        if (manifest == null) return new CharacterPackageVerificationResult(diagnostics);
202	        ValidateManifestPayloads(manifest, files, diagnostics);
203	        ValidateRuntimeAndBindings(files[RuntimePath], files[BindingPath], files[PosePath], manifest, diagnostics);
204	        if (diagnostics.Any(x => x.Severity == CharacterDiagnosticSeverity.Error)) return new CharacterPackageVerificationResult(diagnostics);
205	
206	        string cookedHash = HashFramed(Payloads(files));
207	        if (!StringEquals(manifest.CookedContentHash, cookedHash))
208	            diagnostics.Add(Error("package.hash.cooked-mismatch", "cookedContentHash", "Cooked content hash does not match payload bytes."));
209	        string packageHash = Hash(Concat(FramedBytes(Payloads(files)), WriteManifest(manifest, "")));
210	        if (!StringEquals(manifest.PackageHash, packageHash))
211	            diagnostics.Add(Error("package.hash.package-mismatch", "packageHash", "Package hash does not match payload bytes and placeholder manifest."));
212	        byte[] canonicalManifest = WriteManifest(manifest, manifest.PackageHash);
213	        if (!files[ManifestPath].SequenceEqual(canonicalManifest))
214	            diagnostics.Add(Error("package.manifest.noncanonical", ManifestPath, "Manifest bytes are not the canonical representation."));
215	        return new CharacterPackageVerificationResult(diagnostics);
216	    }
217	
218	    private static void ValidateInput(CharacterPackageAssemblyInput input, List<CharacterDiagnostic> d)
219	    {
220	        if (input == null) { d.Add(Error("package.input.missing", "input", "Assembly input is missing.")); return; }
221	        if (!MatchContentCatalogBuilder.IsStablePackageId(input.PackageId)) d.Add(Error("package.id.invalid", "packageId", "Package ID must be a stable lowercase identifier."));
222	        if (string.IsNullOrEmpty(input.Version)) d.Add(Error("package.version.invalid", "version", "Package version is required."));
223	        if (input.AuthoringSchemaVersion == 0 || input.CookedSchemaVersion == 0) d.Add(Error("package.schema.invalid", "schema", "Schema versions must be non-zero."));
224	        if (string.IsNullOrEmpty(input.RuntimeApiMin) || string.IsNullOrEmpty(input.RuntimeApiMax)) d.Add(Error("package.api.invalid", "runtimeApi", "Runtime API range is required."));
225	        if (!IsLowerHash(input.SourceHash)) d.Add(Error("package.hash.source-invalid", "sourceHash", "Source hash must be lowercase SHA-256 hex."));
226	        if (input.BindingSchemaVersion <= 0 || input.PoseVersion <= 0 || input.SampleRate <= 0 || input.PoseFormat != "SKEL") d.Add(Error("package.toolchain.invalid", "toolchain", "Binding, pose, sample, and format metadata are invalid."));
227	        if (input.RuntimeBytes.Length == 0) d.Add(Error("package.payload.empty", RuntimePath, "Runtime payload is empty."));
228	        if (input.PoseBytes.Length == 0) d.Add(Error("package.payload.empty", PosePath, "Pose payload is empty."));
229	        if (input.BindingBytes.Length == 0) d.Add(Error("package.payload.empty", BindingPath, "Binding payload is empty."));
230	        if (input.CookedPackage.Metadata.PackageId != input.PackageId || input.CookedPackage.Metadata.Version != input.Version || input.CookedPackage.Metadata.CookedSchemaVersion != input.CookedSchemaVersion || input.CookedPackage.Metadata.RuntimeApiMin != input.RuntimeApiMin || input.CookedPackage.Metadata.RuntimeApiMax != input.RuntimeApiMax)
231	            d.Add(Error("package.metadata.mismatch", "cookedPackage.metadata", "Cooked package metadata does not match assembly input."));
232	        if (!input.RuntimeBytes.SequenceEqual(input.CookedPackage.CanonicalBytes)) d.Add(Error("package.runtime.mismatch", RuntimePath, "Runtime payload must equal CookedPackage.CanonicalBytes."));
233	        ValidateUniqueMetadata(input.Dependencies.Select(x => x.PackageId), "dependencies", d);
234	        ValidateUniqueMetadata(input.CapabilityRequirements.Select(x => x.CapabilityId), "capabilityRequirements", d);
235	        foreach (var warning in input.Warnings)
236	        {
237	            if (warning.Severity != CharacterDiagnosticSeverity.Warning)
238	                d.Add(Error("package.warning.invalid", "warnings", "Assembly warnings must have warning severity."));
239	            if (string.IsNullOrEmpty(warning.Code) || string.IsNullOrEmpty(warning.Path))
240	                d.Add(Error("package.warning.invalid", "warnings", "Warnings require code and path."));
241	        }
242	    }
243	
244	    private static void ValidateCrossPayloads(CharacterPackageAssemblyInput input, (string Path, byte[] Bytes)[] payloads, List<CharacterDiagnostic> d)
245	    {
246	        try
247	        {
248	            BindingData binding = ParseBindings(input.BindingBytes, d);
249	            PoseData poses = ParsePoses(input.PoseBytes, d);
250	            HashSet<string> required = RequiredAnimations(input.CookedPackage, d);
251	            if (binding == null || poses == null) return;
252	            ValidateReferences(required, input.CookedPackage.Definition.PresentationIds,
253	                input.CookedPackage.Definition.Slots.Select(slot => slot.HitPresentationId).Where(id => !string.IsNullOrEmpty(id)).Select(id => id!),
254	                binding, poses, d);
255	            if (binding.PackageId != input.PackageId || binding.SourceHash != input.SourceHash || binding.BindingSchemaVersion != input.BindingSchemaVersion || binding.PoseFormat != input.PoseFormat || binding.PoseVersion != input.PoseVersion || binding.SampleRate != input.SampleRate)
256	                d.Add(Error("package.binding.metadata-mismatch", BindingPath, "Binding metadata does not match assembly input."));
257	        }
258	        catch (Exception ex) { d.Add(Error("package.payload.malformed", "payload", ex.Message)); }
259	    }
260	
261	    private static void ValidateManifestPayloads(ManifestData manifest, IReadOnlyDictionary<string, byte[]> files, List<CharacterDiagnostic> d)
262	    {
263	        if (manifest.Payloads.Count != PayloadPaths.Length) { d.Add(Error("package.manifest.payloads", "payloads", "Manifest must contain exactly three payloads.")); return; }
264	        var seenPaths = new HashSet<string>(StringComparer.Ordinal);
265	        for (int i = 0; i < PayloadPaths.Length; i++)
266	        {
267	            var p = manifest.Payloads[i];
268	            if (!seenPaths.Add(p.Path)) d.Add(Error("package.manifest.payload-duplicate", $"payloads[{i}].path", "Manifest contains a duplicate payload path."));
269	            if (p.Path != PayloadPaths[i]) d.Add(Error("package.manifest.payload-order", $"payloads[{i}].path", "Payloads must use the canonical order."));
270	            if (!ExpectedPayloadPath(p.Path) || !files.TryGetValue(p.Path, out byte[] bytes) || bytes == null)
271	            {
272	                d.Add(Error("package.manifest.payload-path", $"payloads[{i}].path", "Manifest payload path is not a canonical package payload."));
273	                continue;
274	            }
