372	        public bool CanPreviewGrab => CanRunScenario && Def.CaptureGeometry != null;
373	        private bool _scenarioPriorShowDummy;
374	        private readonly List<CharacterState> _scenarioActorHistory = new();
375	        private AbilityLabScenarioResult _scenarioTrajectorySource;
376	
377	        public AbilityLabScenarioResult RunScenario(AbilityLabScenarioOptions options)
378	        {
379	            if (options == null) throw new ArgumentNullException(nameof(options));
380	            options.Validate();
381	            if (!CanRunScenario)
382	                throw new InvalidOperationException("Scenario requires an available package runtime, baked poses and rig.");
383	            // Build first: malformed input or unavailable actions cannot alter selection.
384	            var result = _simulationPreviewer.RunScenario(Def, Baked, options, BasePosition(), FacingYaw);
385	            bool airborne = CanonicalSlotProjection.TryGet(options.Action, out var scenarioAddress) && scenarioAddress.IsAirborne;
386	            foreach (var frame in result.Frames)
387	                if (!_previewRenderer.CanPlayScrubbedState(frame.Actor, airborne)
388	                    || !_dummyRenderer.CanPlayScrubbedState(frame.Opponent, false))
389	                    throw new InvalidOperationException($"Scenario animation binding is unavailable at frame {frame.FrameIndex}.");
390	            var priorCursor = CaptureTimelineCursor();
391	            try
392	            {
393	                bool priorDummy = Scenario != null ? _scenarioPriorShowDummy : ShowDummy;
394	                if (CanonicalSlotProjection.TryGet(options.Action, out var address))
395	                {
396	                    Airborne = address.IsAirborne;
397	                    SlotIndex = SlotIndices[Array.IndexOf(SlotNames, address.InputLabel)];
398	                    SelectedSlotId = address.Id;
399	                    StageIndex = 0;
400	                    Tick = 0;
401	                }
402	                Scenario = result;
403	                ScenarioFrame = options.LastFrame;
404	                _scenarioPriorShowDummy = priorDummy;
405	                ShowDummy = true;
406	                Playing = false;
407	                RebuildScenarioTrailHistory();
408	                RefreshPose();
409	                return result;
410	            }
411	            catch
412	            {
413	                RestoreTimelineCursor(priorCursor);
414	                throw;
415	            }
416	        }
417	
418	        public void SelectSharedAction(string action)
419	        {
420	            if (action != "grab") throw new ArgumentException("Unknown shared action.", nameof(action));
421	            var old = Scenario?.Options;
422	            RunScenario(new AbilityLabScenarioOptions(action, old?.LastFrame ?? 60, old?.Distance ?? DummyDistance,
423	                old?.OpponentBehavior ?? AbilityLabOpponentBehavior.Idle, old?.OpponentDamage ?? 0,
424	                old?.RelativeFacingDegrees ?? 180f));
425	            SeekScenario(0);
